/* --- option handlers ------------------------------------------------------*/

static int error_missing(const char *fmt, ...)
{
    /* Just a helper, but we don't use it. */
    (void)fmt;
    return 1;
}

/* Forward decl */
static int handle_option(int argc, char **argv, int *i, bool *stripped,
                         bool *quiet, const char **config_file);

static int handle_option(int argc, char **argv, int *i, bool *stripped,
                         bool *quiet, const char **config_file)
{
    const char *arg = argv[*i];
    char c = arg[1];

    switch (c) {
    case 'h':
    case '?':
        print_usage_to(stdout);
        exit(0);
    case 'v':
        print_version();
        exit(0);
    case 'V':
        print_version_extended();
        exit(0);
    case 's':
        *stripped = true;
        return 0;
    case 'q':
        *quiet = true;
        return 0;
    case 'b':
        setvbuf(stdout, NULL, _IONBF, 0);
        setvbuf(stderr, NULL, _IONBF, 0);
        return 0;
    case 'm':
        /* dump symbol map - not implemented */
        return 0;
    case 'g': {
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        int rc = do_generate(fname, *stripped);
        exit(rc);
    }
    case 'u': {
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        if (strcmp(fname, "-") != 0 && !file_exists(fname)) {
            fprintf(stderr, "error: configuration file %s not found!\n", fname);
            print_usage_to(stderr);
            exit(1);
        }
        int rc = do_update(fname, *stripped);
        exit(rc);
    }
    case 'l': {
        const char *fname = "DoxygenLayout.xml";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        int rc = write_bytes(fname, layout_xml, layout_xml_len);
        exit(rc);
    }
    case 'f': {
        /* -f kind outputFile */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-f\" is missing list specifier.\n");
            print_debug_info();
            exit(1);
        }
        const char *kind = argv[*i+1];
        if (strcmp(kind, "emoji") != 0) {
            fprintf(stderr, "error: option \"-f\" has invalid list specifier.\n");
            exit(1);
        }
        if (*i + 2 >= argc) {
            fprintf(stderr, "error: option \"-f emoji\" is missing an output file name\n");
            exit(1);
        }
        const char *fname = argv[*i+2];
        int rc = write_bytes(fname, emoji_txt, emoji_txt_len);
        exit(rc);
    }
    case 'e': {
        /* -e format file */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-e\" is missing format specifier rtf.\n");
            exit(1);
        }
        const char *fmt = argv[*i+1];
        if (strcmp(fmt, "rtf") != 0) {
            fprintf(stderr, "error: option \"-e\" has invalid format specifier.\n");
            exit(1);
        }
        if (*i + 2 >= argc) {
            fprintf(stderr, "error: option \"-e rtf\" is missing an extensions file name\n");
            exit(1);
        }
        const char *fname = argv[*i+2];
        int rc = write_bytes(fname, rtfext_txt, rtfext_txt_len);
        exit(rc);
    }
    case 'w': {
        /* -w format ... */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-w\" is missing format specifier rtf, html or latex\n");
            exit(1);
        }
        const char *fmt = argv[*i+1];
        if (strcmp(fmt, "rtf") == 0) {
            if (*i + 2 >= argc) {
                fprintf(stderr, "error: option \"-w rtf\" is missing a style sheet file name\n");
                exit(1);
            }
            int rc = write_bytes(argv[*i+2], rtfstyle_txt, rtfstyle_txt_len);
            exit(rc);
        } else if (strcmp(fmt, "html") == 0) {
            if (*i + 4 >= argc) {
                fprintf(stderr, "error: option \"-w html\" does not have enough arguments\n");
                exit(1);
            }
            const char *hfile = argv[*i+2];
            const char *ffile = argv[*i+3];
            const char *sfile = argv[*i+4];
            if (write_bytes(hfile, html_header, html_header_len) != 0) exit(1);
            if (write_bytes(ffile, html_footer, html_footer_len) != 0) exit(1);
            if (write_bytes(sfile, html_style, html_style_len) != 0) exit(1);
            exit(0);
        } else if (strcmp(fmt, "latex") == 0) {
            if (*i + 4 >= argc) {
                fprintf(stderr, "error: option \"-w latex\" does not have enough arguments\n");
                exit(1);
            }
            const char *hfile = argv[*i+2];
            const char *ffile = argv[*i+3];
            const char *sfile = argv[*i+4];
            if (write_bytes(hfile, latex_header, latex_header_len) != 0) exit(1);
            if (write_bytes(ffile, latex_footer, latex_footer_len) != 0) exit(1);
            if (write_bytes(sfile, latex_style, latex_style_len) != 0) exit(1);
            exit(0);
        } else {
            fprintf(stderr,
                "error: Illegal format specifier \"%s\": should be one of rtf, html or latex\n",
                fmt);
            exit(1);
        }
    }
    case 'd': {
        if (*i + 1 >= argc) {
            print_debug_info();
            exit(0);
        }
        const char *lvl = argv[*i+1];
        if (!is_debug_specifier(lvl)) {
            fprintf(stderr, "option \"-d\" has unknown debug specifier: \"%s\".\n", lvl);
            print_debug_info();
            exit(1);
        }
        (*i)++;
        return 0;
    }
    case 'c': {
        if (*i + 1 >= argc) {
            fprintf(stderr, "option \"-c\" is missing the file name to read\n");
            print_debug_info();
            exit(1);
        }
        (*i)++;
        /* Would process file as comment block and emit HTML */
        return 0;
    }
    case 'x': {
        if (strcmp(arg, "-x") != 0 && strcmp(arg, "-x_noenv") != 0) {
            fprintf(stderr, "error: option should be \"-x\" or \"-x_noenv\", found: \"%s\".\n", arg);
            exit(1);
        }
        /* Determine config file */
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        if (strcmp(fname, "-") != 0 && !file_exists(fname)) {
            fprintf(stderr, "error: configuration file %s not found!\n", fname);
            print_usage_to(stderr);
            exit(1);
        }
        fprintf(stdout,
            "# Difference with default Doxyfile 1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\n");
        exit(0);
    }
    default:
        fprintf(stderr, "error: Unknown option \"%s\"\n", arg);
        print_usage_to(stderr);
        exit(1);
    }
    (void)config_file;
    return 0;
}

int main(int argc, char **argv)
{
    if (argc > 0 && argv[0]) g_progname = argv[0];

    bool stripped = false;
    bool quiet = false;
    const char *config_file = NULL;

    int i = 1;
    while (i < argc) {
        const char *arg = argv[i];
        if (arg[0] == '-' && arg[1] != '\0') {
            handle_option(argc, argv, &i, &stripped, &quiet, &config_file);
            /* handle_option may exit, or update i */
        } else if (arg[0] == '-' && arg[1] == '\0') {
            /* '-' means read config from stdin */
            config_file = "-";
        } else {
            config_file = arg;
        }
        i++;
    }

    /* If we reach here, no exit-on-arg happened. Attempt to run docs. */
    if (config_file == NULL) {
        /* Default to Doxyfile if it exists in cwd */
        if (file_exists("Doxyfile")) {
            config_file = "Doxyfile";
        } else {
            fprintf(stderr, "error: Doxyfile not found and no input file specified!\n");
            print_usage_to(stderr);
            return 1;
        }
    }
    return do_run_docs(config_file, quiet);
}
