    return false;
}

/* --- file helpers ---------------------------------------------------------*/

static bool file_exists(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (!f) return false;
    fclose(f);
    return true;
}

/* Read entire file (or stdin) into memory. Returns 0 on success. */
static int read_all(const char *path, char **out_buf, size_t *out_len)
{
    FILE *f = NULL;
    bool is_stdin = (strcmp(path, "-") == 0);
    if (is_stdin) {
        f = stdin;
    } else {
        f = fopen(path, "rb");
        if (!f) return -1;
    }
    size_t cap = 4096, len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { if (!is_stdin) fclose(f); return -1; }
    while (!feof(f) && !ferror(f)) {
        if (len == cap) {
            cap *= 2;
            char *n = (char *)realloc(buf, cap);
            if (!n) { free(buf); if (!is_stdin) fclose(f); return -1; }
            buf = n;
        }
        size_t r = fread(buf + len, 1, cap - len, f);
        len += r;
    }
    if (!is_stdin) fclose(f);
    *out_buf = buf;
    *out_len = len;
    return 0;
}

/* --- update: very simple config-file update ------------------------------*/

/* Parse a simple config line into tag/value. Does not do full doxygen semantics. */
static int find_tag_value(const char *line, char *tag, size_t tag_sz,
                          char **value_start)
{
    /* Skip whitespace */
    const char *p = line;
    while (*p == ' ' || *p == '\t') p++;
    if (*p == '#' || *p == '\0' || *p == '\n') return -1;
    /* Read tag (uppercase/underscore/digit) */
    size_t ti = 0;
    while (*p && (isupper((unsigned char)*p) || *p == '_' ||
                  (*p >= '0' && *p <= '9'))) {
        if (ti + 1 < tag_sz) tag[ti++] = *p;
        p++;
    }
    tag[ti] = '\0';
    if (ti == 0) return -1;
    /* Skip spaces up to '=' */
    while (*p == ' ' || *p == '\t') p++;
    if (*p != '=' && !(*p == '+' && *(p+1) == '=')) return -1;
    if (*p == '+') p += 2;
    else p++;
    while (*p == ' ' || *p == '\t') p++;
    *value_start = (char *)p;
    return 0;
}

/* Update: read existing file, extract tag values, re-emit the template with
 * values preserved. This is an approximation of doxygen -u behaviour. */
static int do_update(const char *filename, bool stripped)
{
    char *buf = NULL; size_t blen = 0;
    if (read_all(filename, &buf, &blen) != 0) {
        fprintf(stderr, "\n\nerror: configuration file %s not found!\n",
                filename);
        print_usage_to(stderr);
        return 1;
    }
    /* Split input into lines and build a table of tag -> value (raw) */
    typedef struct { char tag[64]; char *value; } Entry;
    size_t ecap = 64, ecount = 0;
    Entry *entries = (Entry *)malloc(sizeof(Entry) * ecap);
    if (!entries) { free(buf); return 1; }

    /* Process input line by line. We need to support multi-line continuation
     * with backslash, but we'll do it simply. */
    char *line_start = buf;
    char *end = buf + blen;
    while (line_start < end) {
        char *nl = memchr(line_start, '\n', end - line_start);
        char *line_end = nl ? nl : end;
        /* Build null-terminated line */
        size_t ll = line_end - line_start;
        char *line = (char *)malloc(ll + 1);
        memcpy(line, line_start, ll);
        line[ll] = '\0';
        char tag[64]; char *vstart;
        if (find_tag_value(line, tag, sizeof(tag), &vstart) == 0) {
            /* Build the value: from vstart to end of line, remove CRLF */
            size_t vl = strlen(vstart);
            while (vl > 0 && (vstart[vl-1] == '\r' || vstart[vl-1] == '\n' ||
                              vstart[vl-1] == ' ' || vstart[vl-1] == '\t'))
                vl--;
            char *val = (char *)malloc(vl + 1);
            memcpy(val, vstart, vl);
            val[vl] = '\0';
            if (ecount == ecap) {
                ecap *= 2;
                entries = (Entry *)realloc(entries, sizeof(Entry) * ecap);
            }
            strncpy(entries[ecount].tag, tag, sizeof(entries[0].tag) - 1);
            entries[ecount].tag[sizeof(entries[0].tag)-1] = '\0';
            entries[ecount].value = val;
            ecount++;
        }
        free(line);
        line_start = nl ? nl + 1 : end;
    }

    /* Now emit the template with substituted values */
    FILE *out = NULL;
    bool is_stdout = (strcmp(filename, "-") == 0);
    if (is_stdout) {
        out = stdout;
    } else {
        out = fopen(filename, "wb");
        if (!out) { free(buf); return 1; }
    }
    const unsigned char *tpl = stripped ? doxyfile_stripped_tmpl : doxyfile_tmpl;
    unsigned long tplen = stripped ? doxyfile_stripped_tmpl_len : doxyfile_tmpl_len;

    /* Process template line by line */
    unsigned long pos = 0;
    while (pos < tplen) {
        /* Find end of line */
        unsigned long le = pos;
        while (le < tplen && tpl[le] != '\n') le++;
        /* Extract line */
        size_t ll = le - pos;
        char *line = (char *)malloc(ll + 1);
        memcpy(line, tpl + pos, ll);
        line[ll] = '\0';
        char tag[64]; char *vstart;
        if (find_tag_value(line, tag, sizeof(tag), &vstart) == 0) {
            /* Find user value */
            const char *newval = NULL;
            for (size_t i = 0; i < ecount; i++) {
                if (strcmp(entries[i].tag, tag) == 0) {
                    newval = entries[i].value;
                    break;
                }
            }
            /* Emit "TAG<spaces>= VALUE" with alignment like the template */
            /* Determine the prefix from the template line (up to '=' plus space) */
            char *eq = strchr(line, '=');
            if (eq && newval) {
                /* Print prefix including '= ' */
                fwrite(line, 1, (eq - line) + 1, out);
                if (newval[0] != '\0') fputc(' ', out);
                fputs(newval, out);
                fputc('\n', out);
            } else {
                /* No user value, keep original */
                fwrite(line, 1, ll, out);
                fputc('\n', out);
            }
        } else {
            fwrite(line, 1, ll, out);
            if (le < tplen) fputc('\n', out);
        }
        free(line);
        pos = (le < tplen) ? le + 1 : tplen;
    }

    if (!is_stdout) {
        fclose(out);
        fprintf(stderr, "\n\nConfiguration file '%s' updated.\n\n", filename);
    }
    for (size_t i = 0; i < ecount; i++) free(entries[i].value);
    free(entries);
    free(buf);
    return 0;
}

/* --- generate template ----------------------------------------------------*/

static int do_generate(const char *filename, bool stripped)
{
    const unsigned char *data = stripped ? doxyfile_stripped_tmpl : doxyfile_tmpl;
    unsigned long len = stripped ? doxyfile_stripped_tmpl_len : doxyfile_tmpl_len;
    bool is_stdout = (strcmp(filename, "-") == 0);
    if (write_bytes(filename, data, len) != 0) return 1;
    if (!is_stdout) {
        fprintf(stderr, "\n\nConfiguration file '%s' created.\n\n", filename);
        fputs("Now edit the configuration file and enter\n\n", stderr);
        if (strcmp(filename, "Doxyfile") == 0) {
            fputs("  doxygen\n\n", stderr);
        } else {
            fprintf(stderr, "  doxygen %s\n\n", filename);
        }
        fputs("to generate the documentation for your project\n\n", stderr);
    }
    return 0;
}

/* --- run documentation (stub) --------------------------------------------*/

static int do_run_docs(const char *config_file, bool quiet)
{
    (void)config_file; (void)quiet;
    /* Full documentation generation is not implemented.  Emit a warning
     * similar to what the original tool produces when given an empty
     * configuration. */
    fprintf(stderr,
        "warning: No files to be processed, please check your settings, "
        "in particular INPUT, FILE_PATTERNS, and RECURSIVE\n");
    fprintf(stderr,
        "Doxygen version used: 1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\n");
    fprintf(stderr, "Searching for include files...\n");
    return 0;
}

/* --- option handlers ------------------------------------------------------*/

static int error_missing(const char *fmt, ...)
{
    /* Just a helper, but we don't use it. */
    (void)fmt;
    return 1;
}

/* Forward decl */
static int handle_option(int argc, char **argv, int *i, bool *stripped,
                         bool *quiet, const char **config_file);

static int handle_option(int argc, char **argv, int *i, bool *stripped,
                         bool *quiet, const char **config_file)
{
    const char *arg = argv[*i];
    char c = arg[1];

    switch (c) {
    case 'h':
    case '?':
        print_usage_to(stdout);
        exit(0);
    case 'v':
        print_version();
        exit(0);
    case 'V':
        print_version_extended();
        exit(0);
    case 's':
        *stripped = true;
        return 0;
    case 'q':
        *quiet = true;
        return 0;
    case 'b':
        setvbuf(stdout, NULL, _IONBF, 0);
        setvbuf(stderr, NULL, _IONBF, 0);
        return 0;
    case 'm':
        /* dump symbol map - not implemented */
        return 0;
    case 'g': {
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        int rc = do_generate(fname, *stripped);
        exit(rc);
    }
    case 'u': {
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        if (strcmp(fname, "-") != 0 && !file_exists(fname)) {
            fprintf(stderr, "error: configuration file %s not found!\n", fname);
            print_usage_to(stderr);
            exit(1);
        }
        int rc = do_update(fname, *stripped);
        exit(rc);
    }
    case 'l': {
        const char *fname = "DoxygenLayout.xml";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        int rc = write_bytes(fname, layout_xml, layout_xml_len);
        exit(rc);
    }
    case 'f': {
        /* -f kind outputFile */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-f\" is missing list specifier.\n");
            print_debug_info();
            exit(1);
        }
        const char *kind = argv[*i+1];
        if (strcmp(kind, "emoji") != 0) {
            fprintf(stderr, "error: option \"-f\" has invalid list specifier.\n");
            exit(1);
        }
        if (*i + 2 >= argc) {
            fprintf(stderr, "error: option \"-f emoji\" is missing an output file name\n");
            exit(1);
        }
        const char *fname = argv[*i+2];
        int rc = write_bytes(fname, emoji_txt, emoji_txt_len);
        exit(rc);
    }
    case 'e': {
        /* -e format file */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-e\" is missing format specifier rtf.\n");
            exit(1);
        }
        const char *fmt = argv[*i+1];
        if (strcmp(fmt, "rtf") != 0) {
            fprintf(stderr, "error: option \"-e\" has invalid format specifier.\n");
            exit(1);
        }
        if (*i + 2 >= argc) {
            fprintf(stderr, "error: option \"-e rtf\" is missing an extensions file name\n");
            exit(1);
        }
        const char *fname = argv[*i+2];
        int rc = write_bytes(fname, rtfext_txt, rtfext_txt_len);
        exit(rc);
    }
    case 'w': {
        /* -w format ... */
        if (*i + 1 >= argc) {
            fprintf(stderr, "error: option \"-w\" is missing format specifier rtf, html or latex\n");
            exit(1);
        }
        const char *fmt = argv[*i+1];
        if (strcmp(fmt, "rtf") == 0) {
            if (*i + 2 >= argc) {
                fprintf(stderr, "error: option \"-w rtf\" is missing a style sheet file name\n");
                exit(1);
            }
            int rc = write_bytes(argv[*i+2], rtfstyle_txt, rtfstyle_txt_len);
            exit(rc);
        } else if (strcmp(fmt, "html") == 0) {
            if (*i + 4 >= argc) {
                fprintf(stderr, "error: option \"-w html\" does not have enough arguments\n");
                exit(1);
            }
            const char *hfile = argv[*i+2];
            const char *ffile = argv[*i+3];
            const char *sfile = argv[*i+4];
            if (write_bytes(hfile, html_header, html_header_len) != 0) exit(1);
            if (write_bytes(ffile, html_footer, html_footer_len) != 0) exit(1);
            if (write_bytes(sfile, html_style, html_style_len) != 0) exit(1);
            exit(0);
        } else if (strcmp(fmt, "latex") == 0) {
            if (*i + 4 >= argc) {
                fprintf(stderr, "error: option \"-w latex\" does not have enough arguments\n");
                exit(1);
            }
            const char *hfile = argv[*i+2];
            const char *ffile = argv[*i+3];
            const char *sfile = argv[*i+4];
            if (write_bytes(hfile, latex_header, latex_header_len) != 0) exit(1);
            if (write_bytes(ffile, latex_footer, latex_footer_len) != 0) exit(1);
            if (write_bytes(sfile, latex_style, latex_style_len) != 0) exit(1);
            exit(0);
        } else {
            fprintf(stderr,
                "error: Illegal format specifier \"%s\": should be one of rtf, html or latex\n",
                fmt);
            exit(1);
        }
    }
    case 'd': {
        if (*i + 1 >= argc) {
            print_debug_info();
            exit(0);
        }
        const char *lvl = argv[*i+1];
        if (!is_debug_specifier(lvl)) {
            fprintf(stderr, "option \"-d\" has unknown debug specifier: \"%s\".\n", lvl);
            print_debug_info();
            exit(1);
        }
        (*i)++;
        return 0;
    }
    case 'c': {
        if (*i + 1 >= argc) {
            fprintf(stderr, "option \"-c\" is missing the file name to read\n");
            print_debug_info();
            exit(1);
        }
        (*i)++;
        /* Would process file as comment block and emit HTML */
        return 0;
    }
    case 'x': {
        if (strcmp(arg, "-x") != 0 && strcmp(arg, "-x_noenv") != 0) {
            fprintf(stderr, "error: option should be \"-x\" or \"-x_noenv\", found: \"%s\".\n", arg);
            exit(1);
        }
        /* Determine config file */
        const char *fname = "Doxyfile";
        if (*i + 1 < argc && strcmp(argv[*i+1], "-") == 0) {
            fname = "-";
            (*i)++;
        } else if (*i + 1 < argc && argv[*i+1][0] != '-') {
            fname = argv[*i+1];
            (*i)++;
        }
        if (strcmp(fname, "-") != 0 && !file_exists(fname)) {
            fprintf(stderr, "error: configuration file %s not found!\n", fname);
            print_usage_to(stderr);
            exit(1);
        }
        fprintf(stdout,
            "# Difference with default Doxyfile 1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\n");
        exit(0);
    }
    default:
        fprintf(stderr, "error: Unknown option \"%s\"\n", arg);
        print_usage_to(stderr);
        exit(1);
    }
    (void)config_file;
    return 0;
}

int main(int argc, char **argv)
{
    if (argc > 0 && argv[0]) g_progname = argv[0];

    bool stripped = false;
    bool quiet = false;
    const char *config_file = NULL;

    int i = 1;
    while (i < argc) {
        const char *arg = argv[i];
        if (arg[0] == '-' && arg[1] != '\0') {
            handle_option(argc, argv, &i, &stripped, &quiet, &config_file);
            /* handle_option may exit, or update i */
        } else if (arg[0] == '-' && arg[1] == '\0') {
            /* '-' means read config from stdin */
            config_file = "-";
        } else {
            config_file = arg;
        }
        i++;
    }

    /* If we reach here, no exit-on-arg happened. Attempt to run docs. */
    if (config_file == NULL) {
        /* Default to Doxyfile if it exists in cwd */
        if (file_exists("Doxyfile")) {
            config_file = "Doxyfile";
        } else {
            fprintf(stderr, "error: Doxyfile not found and no input file specified!\n");
            print_usage_to(stderr);
            return 1;
        }
    }
    return do_run_docs(config_file, quiet);
}
